INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (551, 1, '볼륨을 백업하는 방법', '볼륨 `appdata` 의 내용을 호스트 폴더 `/tmp/backup` 에 `tar` 파일로 보관하려 합니다. 볼륨은 도커가 관리하는 저장 공간이라 호스트에서 경로를 바로 다루기 마땅치 않습니다. 가장 알맞은 방법은?', '볼륨의 내용을 다루는 가장 안전한 곳은 그 볼륨을 마운트한 컨테이너 안입니다. 호스트 폴더도 같은 방식으로 컨테이너에 넣을 수 있습니다.', NULL, NULL, '[]', 'choice', '["`docker save appdata` 로 볼륨을 tar 파일로 저장해 호스트 폴더에 둔다", "`docker commit appdata` 로 볼륨을 이미지로 만들어 보관한다", "임시 컨테이너(헬퍼)에 볼륨과 호스트 폴더를 함께 마운트하고, 컨테이너 안에서 tar 로 묶어 호스트 폴더에 쓴다", "`docker cp appdata:/data /tmp/backup` 으로 볼륨 이름을 직접 지정해 복사한다"]', 2, '볼륨 안의 파일은 볼륨을 붙인 컨테이너를 통해 다루는 것이 기본입니다. 일회용 컨테이너(`--rm`)에 `-v 볼륨:/data` 와 `-v 호스트폴더:/backup` 을 같이 붙이고 `tar` 로 묶으면 백업이 호스트에 남습니다. `docker save` 는 이미지용, `docker commit` 은 컨테이너를 이미지로 만드는 명령이고, `docker cp` 는 컨테이너 이름(또는 ID)을 받으며 볼륨 이름은 받지 않습니다.', NULL, NULL, NULL, NULL),
  (551, 2, '헬퍼 컨테이너로 볼륨 안 들여다보기', '볼륨 `appdata` 에 애플리케이션 데이터가 들어 있습니다. 어떤 파일이 있는지 알아야 백업 범위를 정할 수 있습니다. 볼륨을 읽을 때는 **`alpine` 으로 일회용 컨테이너(헬퍼)** 를 띄우고, 볼륨을 `/data` 에 붙인 채 `ls -l` 로 보는 방법이 가장 단순합니다. (`--rm` 은 끝나면 컨테이너를 지우는 옵션, 마운트 뒤에 `:ro` 를 붙이면 읽기 전용)

`appdata` 볼륨의 **파일 목록(하위 폴더 안 포함)** 을 `/tmp/q2.txt` 에 저장하세요.', '`docker run --rm -v 볼륨:경로 이미지 명령` 형태입니다. 하위 폴더 안까지 보려면 `ls` 의 재귀 옵션이 필요합니다. 결과는 `>` 로 파일에 저장합니다.', 'docker run --rm -v appdata:/data:ro alpine ls -lR /data > /tmp/q2.txt
cat /tmp/q2.txt

# 볼륨을 붙인 일회용 컨테이너 안에서 ls 를 실행하면 볼륨 내용이 보인다', '["sh", "-c", "rm -rf /tmp/backup /tmp/q*.txt; docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker image inspect alpine >/dev/null 2>&1 || docker pull -q alpine >/dev/null 2>&1; true\\ndocker run --rm -v appdata:/data alpine sh -c ''echo id=1001 > /data/orders.txt; echo cache=off > /data/app.conf; mkdir /data/logs; echo started > /data/logs/a.log; chown -R 1000:1000 /data'' >/dev/null\\n"]', '["sh", "-c", "( grep -q orders.txt /tmp/q2.txt && grep -q app.conf /tmp/q2.txt ) && ( grep -q a.log /tmp/q2.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "목록에 orders.txt 와 app.conf 가 있다", "cmd": ["sh", "-c", "grep -q orders.txt /tmp/q2.txt && grep -q app.conf /tmp/q2.txt"]}, {"label": "하위 폴더 안의 a.log 도 있다", "cmd": ["sh", "-c", "grep -q a.log /tmp/q2.txt"]}]', '[{"title": "Docker 볼륨: 백업·복원·이전", "url": "https://docs.docker.com/engine/storage/volumes/#back-up-restore-or-migrate-data-volumes"}, {"title": "docker run --volumes-from", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}]'),
  (551, 3, 'tar 로 볼륨 백업하기', '볼륨 `appdata` 를 통째로 백업합니다. 호스트의 `/tmp/backup` 폴더가 이미 있습니다. 헬퍼 컨테이너(`alpine`)에 다음을 붙여 `tar` 로 묶으세요.
- 볼륨 `appdata` → 컨테이너의 `/data` (읽기 전용으로 붙이는 것이 안전합니다)
- 호스트의 `/tmp/backup` → 컨테이너의 `/backup`
- 결과 파일: 호스트의 `/tmp/backup/appdata.tgz` (gzip 압축 tar)

`tar czf 파일 -C 폴더 .` 은 "폴더 **안쪽** 내용을 gzip 압축 tar 로 묶어 파일로 만든다"는 뜻입니다. (`-C 폴더` 는 그 폴더로 이동해서 작업)', '`docker run --rm` 에 `-v` 를 두 번 쓰고, 이미지 뒤에 `tar` 명령을 적습니다. 묶을 위치(`-C`)는 볼륨을 붙인 경로입니다. 결과는 `-C` 가 아니라 아카이브 이름 자리에 `/backup/...` 으로 적습니다.', 'docker run --rm -v appdata:/data:ro -v /tmp/backup:/backup alpine tar czf /backup/appdata.tgz -C /data .
ls -l /tmp/backup

# 헬퍼 컨테이너가 볼륨을 읽어 tar 로 묶고, 결과는 호스트 폴더(/tmp/backup)에 남는다', '["sh", "-c", "rm -rf /tmp/backup /tmp/q*.txt; docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker image inspect alpine >/dev/null 2>&1 || docker pull -q alpine >/dev/null 2>&1; true\\ndocker run --rm -v appdata:/data alpine sh -c ''echo id=1001 > /data/orders.txt; echo cache=off > /data/app.conf; mkdir /data/logs; echo started > /data/logs/a.log; chown -R 1000:1000 /data'' >/dev/null\\nmkdir -p /tmp/backup\\n"]', '["sh", "-c", "( [ -s /tmp/backup/appdata.tgz ] ) && ( L=$(docker run --rm -v /tmp/backup:/b:ro alpine tar tzf /b/appdata.tgz); echo \\"$L\\" | grep -q orders.txt && echo \\"$L\\" | grep -q a.log )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "백업 파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/backup/appdata.tgz ]"]}, {"label": "백업 안에 orders.txt 와 logs/a.log 가 있다", "cmd": ["sh", "-c", "L=$(docker run --rm -v /tmp/backup:/b:ro alpine tar tzf /b/appdata.tgz); echo \\"$L\\" | grep -q orders.txt && echo \\"$L\\" | grep -q a.log"]}]', '[{"title": "Docker 볼륨: 백업·복원·이전", "url": "https://docs.docker.com/engine/storage/volumes/#back-up-restore-or-migrate-data-volumes"}, {"title": "docker run --volumes-from", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}]'),
  (551, 4, '복원 전에 백업 파일 안 확인하기', '`/tmp/backup/appdata.tgz` 백업 파일이 있습니다. 복원하기 전에 **풀지 않고** 안에 무엇이 들었는지 먼저 확인하는 습관이 안전합니다. `tar` 에는 아카이브 내용을 목록으로만 보여 주는 동작이 있습니다. (호스트에서 바로 풀기보다 이번에도 `alpine` 헬퍼에 `/tmp/backup` 을 붙여 확인하세요.)

아카이브 안의 파일 목록을 `/tmp/q4.txt` 에 저장하세요. 아카이브 파일은 건드리지 마세요.', '`tar` 의 동작 글자는 c(만들기)·x(풀기) 말고 목록을 뜻하는 글자도 있습니다. `tar --help` 로 찾아 보세요. 압축 형식(z)과 파일 이름(f)은 백업할 때와 같습니다.', 'docker run --rm -v /tmp/backup:/backup:ro alpine tar tzf /backup/appdata.tgz > /tmp/q4.txt
cat /tmp/q4.txt

# t 는 list. 풀지 않고 목록만 본다', '["sh", "-c", "rm -rf /tmp/backup /tmp/q*.txt; docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker image inspect alpine >/dev/null 2>&1 || docker pull -q alpine >/dev/null 2>&1; true\\ndocker run --rm -v appdata:/data alpine sh -c ''echo id=1001 > /data/orders.txt; echo cache=off > /data/app.conf; mkdir /data/logs; echo started > /data/logs/a.log; chown -R 1000:1000 /data'' >/dev/null\\nmkdir -p /tmp/backup; docker run --rm -v appdata:/data:ro -v /tmp/backup:/backup alpine tar czf /backup/appdata.tgz -C /data . >/dev/null\\n"]', '["sh", "-c", "( grep -q orders.txt /tmp/q4.txt && grep -q app.conf /tmp/q4.txt && grep -q a.log /tmp/q4.txt ) && ( [ -s /tmp/backup/appdata.tgz ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "목록에 orders.txt·app.conf·a.log 가 있다", "cmd": ["sh", "-c", "grep -q orders.txt /tmp/q4.txt && grep -q app.conf /tmp/q4.txt && grep -q a.log /tmp/q4.txt"]}, {"label": "백업 파일이 그대로 있다", "cmd": ["sh", "-c", "[ -s /tmp/backup/appdata.tgz ]"]}]', '[{"title": "Docker 볼륨: 백업·복원·이전", "url": "https://docs.docker.com/engine/storage/volumes/#back-up-restore-or-migrate-data-volumes"}, {"title": "docker run --volumes-from", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}]'),
  (551, 5, '백업 파일 풀기', '볼륨을 `/data` 에 붙인 헬퍼 컨테이너 안에서, gzip 으로 압축된 백업 파일을 **`/data` 안에 풀어 넣는** 명령입니다. 빈칸을 채우세요.', '만들기가 아니라 풀기입니다. 압축 형식과 파일 이름 글자는 그대로 두고 동작 글자만 정하세요.', NULL, NULL, '[]', 'fill', '["xzf", "czf", "tzf", "rzf"]', NULL, '`x` 가 풀기(extract)입니다. `czf` 는 묶어서 만드는 동작이라 파일 목록 인자가 없으면 오류이고, `tzf` 는 목록만 보여 줄 뿐 풀지 않으며, `r` 은 압축 파일에는 추가할 수 없습니다. `-C /data` 는 그 폴더 안으로 풀라는 뜻입니다.', '[0]', 'tar {0} /backup/appdata.tgz -C /data', NULL, NULL),
  (551, 6, '새 볼륨에 복원하기', '`/tmp/backup/appdata.tgz` 는 볼륨 `appdata` 를 백업한 파일입니다. 다른 서버로 옮긴 상황을 흉내 내서, **새 볼륨 `restored`** 에 이 백업을 풀어 넣으세요. `restored` 는 아직 없지만 `-v` 로 처음 붙이면 도커가 만들어 줍니다.

- 헬퍼는 `alpine`, 새 볼륨 → `/data`, `/tmp/backup` → `/backup`(읽기 전용 권장)
- 원래 볼륨 `appdata` 는 건드리지 마세요.

복원 뒤에는 `restored` 안의 파일이 원본과 같아야 하고, 파일의 **주인(uid)도 원본처럼 1000** 이어야 합니다.', '앞 문제에서 본 푸는 동작을 쓰되, 이번에는 `-v` 로 붙이는 볼륨 이름이 새 볼륨입니다. 끝나면 헬퍼로 `ls -ln` 을 해서 확인하세요.', 'docker run --rm -v restored:/data -v /tmp/backup:/backup:ro alpine tar xzf /backup/appdata.tgz -C /data
docker run --rm -v restored:/data:ro alpine ls -lnR /data

# 새 볼륨은 처음 붙일 때 만들어진다. root 로 푸는 tar 는 파일 주인(uid)과 권한도 기록된 그대로 복원한다', '["sh", "-c", "rm -rf /tmp/backup /tmp/q*.txt; docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker image inspect alpine >/dev/null 2>&1 || docker pull -q alpine >/dev/null 2>&1; true\\ndocker run --rm -v appdata:/data alpine sh -c ''echo id=1001 > /data/orders.txt; echo cache=off > /data/app.conf; mkdir /data/logs; echo started > /data/logs/a.log; chown -R 1000:1000 /data'' >/dev/null\\nmkdir -p /tmp/backup; docker run --rm -v appdata:/data:ro -v /tmp/backup:/backup alpine tar czf /backup/appdata.tgz -C /data . >/dev/null\\n"]', '["sh", "-c", "( [ \\"$(docker run --rm -v restored:/data:ro alpine cat /data/orders.txt 2>/dev/null)\\" = id=1001 ] ) && ( [ \\"$(docker run --rm -v restored:/data:ro alpine cat /data/logs/a.log 2>/dev/null)\\" = started ] ) && ( [ \\"$(docker run --rm -v restored:/data:ro alpine stat -c %u /data/orders.txt 2>/dev/null)\\" = 1000 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "restored 볼륨에 orders.txt 내용이 같다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm -v restored:/data:ro alpine cat /data/orders.txt 2>/dev/null)\\" = id=1001 ]"]}, {"label": "하위 폴더 파일 logs/a.log 도 복원됐다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm -v restored:/data:ro alpine cat /data/logs/a.log 2>/dev/null)\\" = started ]"]}, {"label": "파일 주인이 uid 1000 이다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm -v restored:/data:ro alpine stat -c %u /data/orders.txt 2>/dev/null)\\" = 1000 ]"]}]', '[{"title": "Docker 볼륨: 백업·복원·이전", "url": "https://docs.docker.com/engine/storage/volumes/#back-up-restore-or-migrate-data-volumes"}, {"title": "docker run --volumes-from", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}]'),
  (551, 7, '실행 중인 컨테이너의 볼륨 백업하기: --volumes-from', '컨테이너 `db` 가 실행 중이고, 데이터는 컨테이너의 `/var/lib/app` 에 붙은 볼륨에 있습니다. 볼륨 이름이 무엇인지 몰라도 `docker run` 의 **`--volumes-from 컨테이너`** 옵션을 쓰면, 헬퍼 컨테이너에 그 컨테이너와 **같은 경로로 같은 볼륨들**이 붙습니다.

`db` 를 멈추지 않고, `--volumes-from` 을 쓴 헬퍼 `alpine` 으로 `/var/lib/app` 의 내용을 `/tmp/backup/db.tgz` 로 백업하세요. (`/tmp/backup` 은 `/backup` 으로 붙이세요) 여기서는 `--volumes-from` 의 동작을 익히는 연습이고, 실제 DB 라면 10번처럼 멈추거나 덤프 도구를 씁니다.', '`--volumes-from` 뒤에는 컨테이너 이름을 적고, 데이터는 그 컨테이너 안의 경로(`/var/lib/app`) 그대로 보입니다. 호스트 폴더 마운트는 따로 필요합니다.', 'docker run --rm --volumes-from db -v /tmp/backup:/backup alpine tar czf /backup/db.tgz -C /var/lib/app .
tar tzf /tmp/backup/db.tgz 2>/dev/null || docker run --rm -v /tmp/backup:/b:ro alpine tar tzf /b/db.tgz

# --volumes-from 은 지정한 컨테이너의 마운트를 같은 경로로 그대로 물려받는다. 볼륨 이름을 몰라도 된다', '["sh", "-c", "rm -rf /tmp/backup /tmp/q*.txt; docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker image inspect alpine >/dev/null 2>&1 || docker pull -q alpine >/dev/null 2>&1; true\\nmkdir -p /tmp/backup; docker volume create dbdata >/dev/null; docker run --rm -v dbdata:/var/lib/app alpine sh -c ''echo row1 > /var/lib/app/table.dat'' >/dev/null; docker run -d --name db -v dbdata:/var/lib/app alpine sleep 3600 >/dev/null\\n"]', '["sh", "-c", "( [ \\"$(docker inspect -f \\"{{.State.Running}}\\" db 2>/dev/null)\\" = true ] ) && ( docker run --rm -v /tmp/backup:/b:ro alpine tar tzf /b/db.tgz 2>/dev/null | grep -q table.dat )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "db 가 계속 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f \\"{{.State.Running}}\\" db 2>/dev/null)\\" = true ]"]}, {"label": "db.tgz 안에 table.dat 가 있다", "cmd": ["sh", "-c", "docker run --rm -v /tmp/backup:/b:ro alpine tar tzf /b/db.tgz 2>/dev/null | grep -q table.dat"]}]', '[{"title": "Docker 볼륨: 백업·복원·이전", "url": "https://docs.docker.com/engine/storage/volumes/#back-up-restore-or-migrate-data-volumes"}, {"title": "docker run --volumes-from", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}]'),
  (551, 8, '백업 파일의 주인 정하기', '헬퍼 컨테이너는 기본적으로 **root(uid 0)** 로 실행되므로, 호스트 폴더에 쓴 백업 파일의 주인도 root 가 됩니다. 이번에는 백업 담당 계정(uid `1000`, gid `1000`)이 그 파일을 관리해야 합니다. `/tmp/backup` 폴더는 누구나 쓸 수 있게(777) 열려 있고, 볼륨 `appdata` 안의 파일은 모두 uid 1000 소유(누구나 읽기 가능)입니다.

볼륨 `appdata` 를 `/tmp/backup/appdata.tgz` 로 백업하되, 완성된 **파일의 주인이 uid 1000** 이 되게 하세요. (컨테이너 안 프로세스의 실행 사용자는 `docker run` 옵션으로 정할 수 있습니다)', '컨테이너 안에서 새로 만든 파일의 주인은 그 프로세스를 실행한 uid 입니다. `docker run` 에서 실행 사용자를 지정하는 옵션을 찾아 보세요. 결과 파일의 주인은 `ls -ln /tmp/backup` 으로 숫자까지 확인합니다.', 'docker run --rm --user 1000:1000 -v appdata:/data:ro -v /tmp/backup:/backup alpine tar czf /backup/appdata.tgz -C /data .
ls -ln /tmp/backup

# 컨테이너 프로세스의 uid 가 새로 만든 파일의 주인이 된다 (호스트에는 그 uid 의 숫자로 보인다)', '["sh", "-c", "rm -rf /tmp/backup /tmp/q*.txt; docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker image inspect alpine >/dev/null 2>&1 || docker pull -q alpine >/dev/null 2>&1; true\\ndocker run --rm -v appdata:/data alpine sh -c ''echo id=1001 > /data/orders.txt; echo cache=off > /data/app.conf; mkdir /data/logs; echo started > /data/logs/a.log; chown -R 1000:1000 /data'' >/dev/null\\nmkdir -p /tmp/backup; chmod 777 /tmp/backup\\n"]', '["sh", "-c", "( docker run --rm -v /tmp/backup:/b:ro alpine tar tzf /b/appdata.tgz 2>/dev/null | grep -q orders.txt ) && ( [ \\"$(stat -c %u /tmp/backup/appdata.tgz 2>/dev/null)\\" = 1000 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "백업 파일이 있고 내용이 정상이다", "cmd": ["sh", "-c", "docker run --rm -v /tmp/backup:/b:ro alpine tar tzf /b/appdata.tgz 2>/dev/null | grep -q orders.txt"]}, {"label": "백업 파일의 주인이 uid 1000 이다", "cmd": ["sh", "-c", "[ \\"$(stat -c %u /tmp/backup/appdata.tgz 2>/dev/null)\\" = 1000 ]"]}]', '[{"title": "Docker 볼륨: 백업·복원·이전", "url": "https://docs.docker.com/engine/storage/volumes/#back-up-restore-or-migrate-data-volumes"}, {"title": "docker run --volumes-from", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}]'),
  (551, 9, '볼륨을 소유자 그대로 옮기기', '아카이브 파일 없이 볼륨 `appdata` 의 내용을 새 볼륨 `newdata` 로 **바로 복사**하려 합니다. 헬퍼 컨테이너에 두 볼륨(`appdata` → `/from`(읽기 전용), `newdata` → `/to`)을 함께 붙이고 `cp` 로 옮기세요.

옮긴 뒤 `newdata` 에도 `orders.txt` 와 `logs/a.log` 가 있어야 하고, 파일의 **주인(uid 1000)과 권한이 원본 그대로** 여야 합니다. (`cp` 의 옵션에 따라 소유자 보존 여부가 달라집니다. `/from/.` 은 숨김 파일까지 포함한 안쪽 전체를 뜻합니다)', '`cp` 에는 재귀 복사(-r)와 별도로 소유자·권한까지 그대로 가져오는 옵션이 있습니다. `cp --help` 로 찾아 보세요. 결과는 `ls -ln` 으로 숫자 uid 를 비교하세요.', 'docker run --rm -v appdata:/from:ro -v newdata:/to alpine cp -a /from/. /to/
docker run --rm -v newdata:/to:ro alpine ls -lnR /to

# -a 는 소유자·권한·하위 폴더를 모두 보존한다. -r 만 쓰면 root 가 만든 새 파일이 돼 주인이 root 로 바뀐다', '["sh", "-c", "rm -rf /tmp/backup /tmp/q*.txt; docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker image inspect alpine >/dev/null 2>&1 || docker pull -q alpine >/dev/null 2>&1; true\\ndocker run --rm -v appdata:/data alpine sh -c ''echo id=1001 > /data/orders.txt; echo cache=off > /data/app.conf; mkdir /data/logs; echo started > /data/logs/a.log; chown -R 1000:1000 /data'' >/dev/null\\n"]', '["sh", "-c", "( [ \\"$(docker run --rm -v newdata:/d:ro alpine cat /d/orders.txt /d/logs/a.log 2>/dev/null | tr \\"\\\\n\\" \\" \\")\\" = \\"id=1001 started \\" ] ) && ( [ \\"$(docker run --rm -v newdata:/d:ro alpine stat -c %u /d/orders.txt /d/logs/a.log 2>/dev/null | tr \\"\\\\n\\" \\" \\")\\" = \\"1000 1000 \\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "newdata 에 orders.txt 와 logs/a.log 가 있다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm -v newdata:/d:ro alpine cat /d/orders.txt /d/logs/a.log 2>/dev/null | tr \\"\\\\n\\" \\" \\")\\" = \\"id=1001 started \\" ]"]}, {"label": "파일 주인이 uid 1000 이다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm -v newdata:/d:ro alpine stat -c %u /d/orders.txt /d/logs/a.log 2>/dev/null | tr \\"\\\\n\\" \\" \\")\\" = \\"1000 1000 \\" ]"]}]', '[{"title": "Docker 볼륨: 백업·복원·이전", "url": "https://docs.docker.com/engine/storage/volumes/#back-up-restore-or-migrate-data-volumes"}, {"title": "docker run --volumes-from", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}]'),
  (551, 10, '쓰는 도중인 데이터베이스 볼륨 백업', '데이터베이스 컨테이너가 **한창 쓰는 중**인 볼륨을 `tar` 로 묶어 백업하려 합니다. 이에 대한 설명으로 가장 알맞은 것은?', 'tar 는 파일을 읽는 도구일 뿐입니다. 읽는 동안 다른 프로세스가 파일을 바꾸면 어떻게 될지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["볼륨을 읽기 전용으로 붙이면 쓰는 중인 파일도 일관된 상태로 읽혀 안전하다", "묶는 동안 파일이 바뀌면 서로 맞지 않는 상태가 담겨 복원이 안 될 수 있으니, 멈추거나 덤프 도구를 쓰는 편이 안전하다", "tar 가 읽는 동안 파일을 알아서 잠가 주므로 그대로 묶어도 안전하다", "`--volumes-from` 으로 붙이면 도커가 스냅숏을 만들어 주므로 그대로 묶어도 안전하다"]', 1, '일반 파일 복사나 tar 는 읽는 도중 바뀌는 내용을 막아 주지 않아, 데이터베이스처럼 여러 파일이 맞물린 데이터는 깨진 백업이 될 수 있습니다. 컨테이너를 멈춘 뒤 백업하거나, DB 전용 덤프 도구(`mysqldump` 등)를 쓰는 것이 안전합니다. 읽기 전용 마운트(`:ro`)는 헬퍼가 쓰지 못하게 할 뿐 원본이 바뀌는 것을 막지 않고, `--volumes-from` 도 스냅숏을 만들지 않습니다.', NULL, NULL, NULL, NULL),
  (551, 11, '백업이 Permission denied 로 실패한다', '볼륨 `vault` 안에는 root 만 읽을 수 있는 파일(`secret.txt`, 권한 600, 주인 root)이 있습니다. 백업 스크립트를 일반 사용자(uid 1000)로 실행했더니 실패합니다.

1. 아래 명령을 실행해 나오는 **오류 메시지**를 `/tmp/q11.txt` 에 저장하세요.
`docker run --rm --user 1000:1000 -v vault:/data:ro -v /tmp/backup:/backup alpine tar czf /backup/vault.tgz -C /data .`
2. 원인을 고쳐 `/tmp/backup/vault.tgz` 안에 `secret.txt` 가 들어가게 백업하세요. (`/tmp/backup` 은 누구나 쓸 수 있게 열려 있고, 볼륨의 파일 권한은 바꾸지 마세요)', '오류는 표준 오류(`2>`)로 저장합니다. 파일을 읽을 수 없는 이유는 실행 사용자와 파일 권한의 관계에 있습니다. 헬퍼의 사용자를 어떻게 하면 모든 파일을 읽을 수 있을지 생각해 보세요.', 'docker run --rm --user 1000:1000 -v vault:/data:ro -v /tmp/backup:/backup alpine tar czf /backup/vault.tgz -C /data . 2> /tmp/q11.txt
cat /tmp/q11.txt
rm -f /tmp/backup/vault.tgz
docker run --rm -v vault:/data:ro -v /tmp/backup:/backup alpine tar czf /backup/vault.tgz -C /data .

# 읽기 권한이 root 에게만 있는 파일은 일반 uid 로 묶을 수 없다. 백업용 헬퍼는 root(기본값)로 실행한다', '["sh", "-c", "rm -rf /tmp/backup /tmp/q*.txt; docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker image inspect alpine >/dev/null 2>&1 || docker pull -q alpine >/dev/null 2>&1; true\\nmkdir -p /tmp/backup; chmod 777 /tmp/backup; docker run --rm -v vault:/data alpine sh -c ''echo token=abc > /data/secret.txt; chmod 600 /data/secret.txt; chown 0:0 /data/secret.txt'' >/dev/null\\n"]', '["sh", "-c", "( grep -qi \\"permission denied\\" /tmp/q11.txt ) && ( docker run --rm -v /tmp/backup:/b:ro alpine tar tzf /b/vault.tgz 2>/dev/null | grep -q secret.txt ) && ( [ \\"$(docker run --rm -v vault:/d:ro alpine stat -c %a /d/secret.txt 2>/dev/null)\\" = 600 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "오류 메시지가 저장돼 있다", "cmd": ["sh", "-c", "grep -qi \\"permission denied\\" /tmp/q11.txt"]}, {"label": "vault.tgz 안에 secret.txt 가 있다", "cmd": ["sh", "-c", "docker run --rm -v /tmp/backup:/b:ro alpine tar tzf /b/vault.tgz 2>/dev/null | grep -q secret.txt"]}, {"label": "원본 파일 권한은 그대로 600 이다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm -v vault:/d:ro alpine stat -c %a /d/secret.txt 2>/dev/null)\\" = 600 ]"]}]', '[{"title": "Docker 볼륨: 백업·복원·이전", "url": "https://docs.docker.com/engine/storage/volumes/#back-up-restore-or-migrate-data-volumes"}, {"title": "docker run --volumes-from", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}]'),
  (551, 12, '볼륨 이전 절차', '쓰기 작업을 하는 컨테이너 `db` 의 볼륨을 **새 볼륨**으로 옮기려 합니다. 안전한 순서로 카드를 놓으세요. (백업 전에 데이터가 더 바뀌지 않게 쓰는 컨테이너를 먼저 멈추고, 아카이브 내용 확인은 복원하기 전에 합니다.)', '데이터가 바뀌는 중에 묶으면 안 됩니다. 확인은 풀기 전에 한 번, 복원 뒤에 한 번 있습니다.', NULL, NULL, '[]', 'order', '["헬퍼 컨테이너로 원래 볼륨을 tar 로 묶어 백업 파일을 만든다", "복원된 새 볼륨의 파일을 헬퍼로 `ls -l` 해서 확인한다", "쓰기 작업을 하는 `db` 컨테이너를 멈춘다", "헬퍼로 새 볼륨에 백업 파일을 풀어 넣는다", "`tar tzf` 로 백업 파일 안의 목록을 확인한다"]', NULL, '쓰는 컨테이너를 멈춰 일관된 상태를 만든 뒤(`docker stop`), 헬퍼로 tar 백업을 만들고, 풀기 전에 `tar tzf` 로 내용을 확인합니다. 그다음 새 볼륨에 `tar xzf` 로 복원하고, 마지막으로 복원된 볼륨의 내용과 소유자를 확인합니다.', '[2, 0, 4, 3, 1]', NULL, NULL, NULL);
